  attachments.registerCategories("AP_PAYMENT",Map.of("PAYMENT_OUT_PROOF",Set.of("COST","BANK_INFO")));
  attachments.registerCategories("AP_PREPAYMENT",Map.of("PAYMENT_OUT_PROOF",Set.of("COST","BANK_INFO")));
